ORIGINAL_WAIT_SOURCE = "if frame.stack_cursor is not None:\n    raise SceneRefreshBoundary(199312, frame, None)\nmemory.state.progress('message-scene')"
EXPECTED_WAIT_AST = "Assign(targets=[Name(id='frame', ctx=Store())], value=Yield(value=Call(func=Attribute(value=Call(func=Name(id='ForceTurnWait', ctx=Load()), args=[Attribute(value=Name(id='memory', ctx=Load()), attr='state', ctx=Load()), Name(id='frame', ctx=Load()), Constant(value=199312)], keywords=[]), attr='validate', ctx=Load()), args=[], keywords=[])))"

def admit_force_turn_program(source, owner_sources):
    tree = ast.parse(source)
    if ast.dump(tree, include_attributes=False) != EXPECTED_MODULE_AST:
        raise ValueError('force-turn module differs from the complete frozen AST')
    for module, original_name, program_name in OWNERS:
        current = next(node for node in ast.parse(owner_sources[module]).body if isinstance(node, ast.FunctionDef) and node.name == original_name)
        if ast.dump(current, include_attributes=False) != EXPECTED_OWNER_ASTS[original_name]:
            raise ValueError('original force-turn dependency changed: ' + original_name)
        program = copy.deepcopy(next(node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == program_name))
        program.name = original_name
        changes = 0
        if program_name == 'force_turn_message_program':
            for loop in ast.walk(program):
                if isinstance(loop, ast.While):
                    for index, statement in enumerate(loop.body):
                        if isinstance(statement, ast.Assign) and isinstance(statement.value, ast.Yield):
                            if ast.dump(statement, include_attributes=False) != EXPECTED_WAIT_AST:
                                raise ValueError('unexpected original force-turn cooperative wait')
                            loop.body[index:index+1] = ast.parse(ORIGINAL_WAIT_SOURCE).body
                            changes += 1
        else:
            replacement = '_campaign_call_fields' if program_name == 'force_turn_screen_program' else 'display_call_fields'
            expected = ('_force_turn_owner_call_steps',) if program_name == 'force_turn_screen_program' else ('_force_turn_message_call_steps', 'command_assignment_call_program', 'command_finish_assignment_call_program')
            for statement in ast.walk(program):
                if isinstance(statement, ast.Assign) and isinstance(statement.value, ast.YieldFrom):
                    call = statement.value.value
                    if not isinstance(call, ast.Call) or not isinstance(call.func, ast.Name) or call.func.id not in expected:
                        raise ValueError('unexpected original force-turn cooperative child')
                    call.func.id = replacement
                    statement.value = call
                    changes += 1
        if program_name == 'force_turn_first_program':
            for statement in ast.walk(program):
                if isinstance(statement, ast.Return) and isinstance(statement.value, ast.YieldFrom):
                    call = statement.value.value
                    if not (isinstance(call, ast.Call) and isinstance(call.func, ast.Name)
                            and call.func.id == 'command_second_force_program'):
                        raise ValueError('unexpected first-to-second force cooperative tail')
                    call.func.id = '_diplomacy_second_force_turn_fields'
                    statement.value = call
                    changes += 1
        if changes != (4 if program_name == 'force_turn_first_program' else 1) or ast.dump(program, include_attributes=False) != EXPECTED_OWNER_ASTS[original_name]:
            raise ValueError('force-turn does not reverse to the entire original owner: ' + original_name)
    from pathlib import Path
    from .compiler_command_message_steps import admit_command_message_source
    directory = Path(__file__).resolve().parent
    admit_command_message_source((directory / 'command_message_steps.py').read_text(encoding='utf-8'), {
        'highbank': (directory.parent / 'high_level_remaining_flows/business_highbank.py').read_text(encoding='utf-8'),
        'support': (directory / 'business_scene_support.py').read_text(encoding='utf-8'),
        'gameplay': (directory / 'business_gameplay.py').read_text(encoding='utf-8'),
        'display': (directory / 'contexts_display_fields.py').read_text(encoding='utf-8'),
        'city': (directory.parent / 'high_level_remaining_flows/business_city.py').read_text(encoding='utf-8'),
        'commands': (directory / 'business_commands.py').read_text(encoding='utf-8'),
        'main': (directory / 'business_main.py').read_text(encoding='utf-8')})
    return dict(whole_original_owners=(0x484, 0x30960, 0x30A74), wait=0x30A90,
        complete_module_AST=True, complete_original_algorithms_restored=True,
        native_lowerers_changed=False, new_formal_bytes=0)
